// Опрос Telegram: забираем новые сообщения (без вебхука — работает на http-сервере)
const BOT_TOKEN = 'ВСТАВЬ_ТОКЕН_БОТА';
const FB = 'https://ocean-crm-c8bcf-default-rtdb.europe-west1.firebasedatabase.app';
const FB_API_KEY = 'AIzaSyBo3gJb9XIuK_12ZSwTvQkk1XQ-tGI5nYY'; // Web API Key — не секрет
const BOT_EMAIL = 'ВСТАВЬ_ПОЧТУ_ДЛЯ_ВХОДА';
const BOT_PASSWORD = 'ВСТАВЬ_ПАРОЛЬ_ДЛЯ_ВХОДА';
const base = 'https://api.telegram.org/bot' + BOT_TOKEN;

// 0) входим в Firebase (email+пароль), получаем токен доступа к базе
let idToken = '';
try {
  const auth = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://identitytoolkit.googleapis.com/v1/accounts:signInWithPassword?key=' + FB_API_KEY,
    body: { email: BOT_EMAIL, password: BOT_PASSWORD, returnSecureToken: true },
    json: true
  });
  idToken = auth.idToken;
} catch (e) { return []; } // без входа в закрытую базу не достучимся

// 1) загружаем сохранённый offset (id последнего обработанного апдейта)
let offset = 0;
try {
  const o = await this.helpers.httpRequest({ method: 'GET', url: FB + '/bot_offset.json?auth=' + idToken, json: true });
  if (typeof o === 'number') offset = o;
} catch (e) {}

// 2) getUpdates (если висит старый вебхук — снимаем и пробуем снова)
const qs = { timeout: 0, allowed_updates: JSON.stringify(['message']) };
if (offset > 0) qs.offset = offset;
let resp;
try {
  resp = await this.helpers.httpRequest({ method: 'GET', url: base + '/getUpdates', qs, json: true });
} catch (e) {
  try { await this.helpers.httpRequest({ method: 'POST', url: base + '/deleteWebhook', json: true }); } catch (e2) {}
  try { resp = await this.helpers.httpRequest({ method: 'GET', url: base + '/getUpdates', qs, json: true }); }
  catch (e3) { return []; }
}
const updates = (resp && resp.result) || [];
if (!updates.length) return [];

// 3) сдвигаем offset за последний апдейт (чтобы не обрабатывать повторно)
const maxId = Math.max.apply(null, updates.map(u => u.update_id));
try { await this.helpers.httpRequest({ method: 'PUT', url: FB + '/bot_offset.json?auth=' + idToken, body: maxId + 1, json: true }); } catch (e) {}

// 4) отдаём вниз только текстовые сообщения из ЛИЧНЫХ чатов (в группах бот молчит)
const out = [];
for (const u of updates) {
  const m = u.message;
  if (!m || !m.text) continue;
  const chat = m.chat || {};
  if (chat.type !== 'private') continue;
  out.push({ json: {
    chatId: chat.id,
    userText: m.text,
    first_name: chat.first_name || '',
    last_name: chat.last_name || '',
    username: chat.username || '',
    idToken: idToken
  }});
}
return out;

// Разбираем ответ YandexGPT: чистим текст, ловим метку заявки, готовим новую память
const c1 = $('Собрать запрос').item.json;
const resp = $json;

let text = '';
try { text = resp.result.alternatives[0].message.text || ''; } catch (e) { text = ''; }

const m = text.match(/#LEAD#\s*(\{[\s\S]*?\})/);
let reply = text.replace(/#LEAD#[\s\S]*$/, '').trim();
if (!reply) reply = 'Спасибо! Я всё записала, мы скоро с вами свяжемся 🌊';

// Заявку считаем валидной только если есть имя ребёнка, имя родителя и настоящий телефон
function validLead(l) {
  if (!l || typeof l !== 'object') return false;
  const ph = String(l.phone || '').replace(/\D/g, '');
  if (ph.length < 10) return false;
  if (!l.child_name || !l.parent_name) return false;
  return true;
}

let lead = null;
if (m && !c1.leadSaved) {
  try {
    const parsed = JSON.parse(m[1]);
    if (validLead(parsed)) lead = parsed;
  } catch (e) { lead = null; }
}

const newMessages = [
  ...(c1.history || []),
  { role: 'user', text: c1.userText },
  { role: 'assistant', text: reply }
].slice(-16);

const state = {
  messages: newMessages,
  leadSaved: c1.leadSaved || !!lead,
  parent: c1.parent,
  paused: c1.paused,
  updated: new Date().toISOString()
};

return [{ json: { chatId: c1.chatId, reply, hasLead: !!lead, lead: lead || {}, state, idToken: c1.idToken } }];
